create extension if not exists pgcrypto;
create table if not exists bm_inventory (id text primary key, name text, provider_state text, provider_health_raw jsonb, health_normalized text, verification_raw jsonb, verification_normalized text, internal_classification text check (internal_classification in ('BM0','BM3','BM5','BM10')), region_code text, ip_region_metadata jsonb, limit_metadata jsonb, provider_updated_at timestamptz, internal_updated_at timestamptz default now());
create table if not exists ad_account_inventory (id text primary key, bm_id text references bm_inventory(id), name text, provider_state text, share_eligible boolean default false, provider_metadata jsonb, updated_at timestamptz default now());
create table if not exists bm_batch_jobs (id uuid primary key default gen_random_uuid(), requested_by text not null, idempotency_key text unique not null, quantity int not null check(quantity between 1 and 100), naming_template text not null, requested_rate_per_minute numeric not null, state text not null check(state in ('queued','running','paused','completed','failed','cancelled')), processed_count int default 0, error_class text, reconcile_required boolean default false, created_at timestamptz default now(), updated_at timestamptz default now(), started_at timestamptz);
create table if not exists bm_batch_items (id uuid primary key default gen_random_uuid(), job_id uuid references bm_batch_jobs(id) on delete cascade, item_no int not null, idempotency_key text unique not null, state text not null, provider_reference text, error_class text, reconcile_required boolean default false, created_at timestamptz default now(), updated_at timestamptz default now(), unique(job_id,item_no));
create table if not exists admin_invitations (id uuid primary key default gen_random_uuid(), bm_id text references bm_inventory(id), email text not null, requested_role text not null, requested_by text not null, idempotency_key text unique not null, state text not null, provider_capability text not null, provider_reference text, error_class text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists partner_share_jobs (id uuid primary key default gen_random_uuid(), source_bm_id text references bm_inventory(id), partner_business_id text not null, requested_by text not null, idempotency_key text unique not null, preview_hash text not null, preview_payload jsonb not null, state text not null, provider_capability text not null, error_class text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists partner_share_items (id uuid primary key default gen_random_uuid(), job_id uuid references partner_share_jobs(id) on delete cascade, ad_account_id text references ad_account_inventory(id), state text not null, provider_reference text, error_class text, reconcile_required boolean default false, created_at timestamptz default now(), updated_at timestamptz default now(), unique(job_id,ad_account_id));
create table if not exists audit_events (id bigserial primary key, actor_id text not null, actor_role text not null, action text not null, resource_type text not null, resource_id text, result text not null, error_class text, metadata jsonb default '{}'::jsonb, created_at timestamptz default now());
create index if not exists idx_bm_jobs_state on bm_batch_jobs(state,created_at); create index if not exists idx_invites_state on admin_invitations(state,created_at); create index if not exists idx_share_items_state on partner_share_items(state,created_at);
